def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                cells.setdefault(grid[r][c], []).append((r, c))

    frames = []
    for color, pts in cells.items():
        r0 = min(r for r, c in pts)
        r1 = max(r for r, c in pts)
        c0 = min(c for r, c in pts)
        c1 = max(c for r, c in pts)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        occupied = set(pts)
        border = (
            all((r0, c) in occupied for c in range(c0, c1 + 1))
            and all((r1, c) in occupied for c in range(c0, c1 + 1))
            and all((r, c0) in occupied for r in range(r0, r1 + 1))
            and all((r, c1) in occupied for r in range(r0, r1 + 1))
        )
        if border:
            interior = {
                (r - r0, c - c0)
                for r, c in pts
                if r0 < r < r1 and c0 < c < c1
            }
            frames.append({
                "color": color, "r0": r0, "r1": r1,
                "c0": c0, "c1": c1, "interior": interior
            })

    sources = [f for f in frames if f["interior"]]
    if not sources:
        return [row[:] for row in grid]
    source = sources[0]
    sh = source["r1"] - source["r0"] + 1
    sw = source["c1"] - source["c0"] + 1

    out = [[0] * w for _ in range(h)]

    # Keep the patterned source unchanged.
    for r, c in cells[source["color"]]:
        out[r][c] = source["color"]

    # Copy its interior pattern into frames of the same dimensions.
    for frame in frames:
        if frame is source:
            continue
        fh = frame["r1"] - frame["r0"] + 1
        fw = frame["c1"] - frame["c0"] + 1
        if (fh, fw) != (sh, sw):
            continue

        color = frame["color"]
        for c in range(frame["c0"], frame["c1"] + 1):
            out[frame["r0"]][c] = color
            out[frame["r1"]][c] = color
        for r in range(frame["r0"], frame["r1"] + 1):
            out[r][frame["c0"]] = color
            out[r][frame["c1"]] = color
        for dr, dc in source["interior"]:
            out[frame["r0"] + dr][frame["c0"] + dc] = color

    return out
